def blog_hub(b):
    path = "/blog/"; d = depth_of(path); L = lambda x: link(b, x, d); url = DOMAIN + path
    posts = "".join(f"<a class='post' href='{L(a['path'])}'><span class='meta'>{esc(a['eyebrow'])}</span><h3>{a['h1']}</h3><p>{esc(a['meta'])}</p></a>" for a in ARTICLES)
    body = f"""{crumbs_html(b, d, [HOME, BLOG])}
<section class="page-hero"><div class="wrap" style="grid-template-columns:1fr"><div class="stack article-head"><p class="eyebrow">Blog</p><h1>Guides for homeowners financing a project, and contractors financing a business</h1><p class="answer-first" id="speakable-summary">Practical, sourced guides on paying for roofs, HVAC and home improvements, and on offering financing and getting capital as a contractor. Every article is attached to a page that explains the financing it describes. No rate promises, no guaranteed approvals.</p></div></div></section>
<section><div class="wrap"><div class="post-list">{posts}</div></div></section>
{contact_section(b, d)}"""
    schema = [
        {"@type": "CollectionPage", "@id": url + "#webpage", "url": url, "name": "Blog | AL Elite Financing", "isPartOf": {"@id": DOMAIN + "/#website"}, "dateModified": "2026-10-04", "inLanguage": "en-US"},
        {"@type": "ItemList", "itemListElement": [{"@type": "ListItem", "position": i + 1, "name": strip_tags(a["h1"]), "url": DOMAIN + a["path"]} for i, a in enumerate(ARTICLES)]},
        breadcrumb_schema([HOME, BLOG]),
    ]
    return page(b, path, "Financing Guides for Homeowners & Contractors | Blog | AL Elite", "Guides on roof, HVAC and home improvement financing for homeowners, and on customer financing and business capital for contractors. Sourced, plain-English, no rate promises.", body, schema)
